package it.unipd.dei.webapp.database.worker;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

import it.unipd.dei.webapp.database.AbstractDAO;
import it.unipd.dei.webapp.resource.movie.Worker;

/**
 * Inserts a new worker into the database and retrieves the auto-generated ID.
 * @author Wise Team
 * @version 1.0
 * @since 1.0
 */
public final class CreateWorkerDAO extends AbstractDAO<Worker> {

    /**
     * The SQL statement to insert the worker and return the new record.
     */
    private static final String STATEMENT = "INSERT INTO Worker (name, surname) VALUES (?, ?) RETURNING *";

    /**
     * The worker data to be stored.
     */
    private final Worker worker;

    /**
     * Creates a new object to store a worker in the database.
     *
     * @param con    the database connection.
     * @param worker the worker to be stored.
     */
    public CreateWorkerDAO(final Connection con, final Worker worker) {
        super(con);

        if (worker == null) {
            LOGGER.error("The worker cannot be null.");
            throw new NullPointerException("The worker cannot be null.");
        }

        this.worker = worker;
    }

    @Override
    protected void doAccess() throws SQLException {
        try (PreparedStatement pstmt = con.prepareStatement(STATEMENT)) {
            pstmt.setString(1, worker.getName());
            pstmt.setString(2, worker.getSurname());

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    // Construct the output worker with the ID generated by the DB
                    outputParam = new Worker(
                            rs.getInt("worker_id"),
                            rs.getString("name"),
                            rs.getString("surname")
                    );

                    LOGGER.info("Worker %s %s successfully created with ID %d.",
                            outputParam.getName(), outputParam.getSurname(), outputParam.getId());
                }
            }
        }
    }
}